import express, { Request, Response, NextFunction } from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import argon2 from 'argon2';

const app = express();
app.use(express.json());

interface UserSession {
  userId: string;
  role: 'admin' | 'user' | 'readonly';
  tenantId: string;
}

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'appdb',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  ssl: { rejectUnauthorized: true }
});

const sessions = new Map<string, UserSession>();

const ALLOWED_REDIRECT_ORIGINS = [
  'https://app.example.com',
  'https://dashboard.example.com',
  'https://admin.example.com'
];

function normalizeUrl(input: string): URL | null {
  try {
    const decoded = decodeURIComponent(input);
    return new URL(decoded);
  } catch {
    return null;
  }
}

function isAllowedOrigin(url: URL): boolean {
  const origin = url.origin;
  return ALLOWED_REDIRECT_ORIGINS.some(allowed => origin.endsWith(allowed.replace('https://', '')));
}

function buildRedirectTarget(basePath: string, callbackUrl: string, token: string): string {
  const url = normalizeUrl(callbackUrl);
  if (!url) {
    return `${basePath}/error?reason=invalid_callback`;
  }
  if (!isAllowedOrigin(url)) {
    return `${basePath}/error?reason=unauthorized_origin`;
  }
  url.searchParams.set('auth_token', token);
  return url.toString();
}

async function authenticateSession(req: Request, res: Response, next: NextFunction) {
  const sessionId = req.headers['x-session-id'] as string;
  if (!sessionId || !sessions.has(sessionId)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  (req as any).session = sessions.get(sessionId);
  next();
}

function requireRole(...roles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const session = (req as any).session as UserSession;
    if (!roles.includes(session.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

app.post('/api/auth/login', async (req: Request, res: Response) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: 'Missing credentials' });
  }

  const result = await pool.query(
    'SELECT id, password_hash, role, tenant_id FROM users WHERE username = $1',
    [username]
  );

  if (result.rows.length === 0) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const user = result.rows[0];
  const valid = await argon2.verify(user.password_hash, password);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const sessionId = crypto.randomBytes(32).toString('hex');
  sessions.set(sessionId, {
    userId: user.id,
    role: user.role,
    tenantId: user.tenant_id
  });

  return res.json({ sessionId });
});

app.get('/api/auth/callback', authenticateSession, async (req: Request, res: Response) => {
  const session = (req as any).session as UserSession;
  const callbackUrl = req.query.redirect_uri as string;

  if (!callbackUrl) {
    return res.status(400).json({ error: 'Missing redirect_uri' });
  }

  const tokenResult = await pool.query(
    'INSERT INTO auth_tokens (user_id, tenant_id, token, expires_at) VALUES ($1, $2, $3, NOW() + interval \'15 minutes\') RETURNING token',
    [session.userId, session.tenantId, crypto.randomBytes(32).toString('hex')]
  );

  const token = tokenResult.rows[0].token;
  const basePath = `https://${req.get('host')}`;
  const target = buildRedirectTarget(basePath, callbackUrl, token);

  return res.redirect(302, target);
});

app.get('/api/connections', authenticateSession, requireRole('admin', 'user'), async (req: Request, res: Response) => {
  const session = (req as any).session as UserSession;
  const result = await pool.query(
    'SELECT id, name, host, port, database_name, created_at FROM db_connections WHERE tenant_id = $1',
    [session.tenantId]
  );
  return res.json({ connections: result.rows });
});

app.post('/api/connections', authenticateSession, requireRole('admin'), async (req: Request, res: Response) => {
  const session = (req as any).session as UserSession;
  const { name, host, port, databaseName, username, password } = req.body;

  if (!name || !host || !port || !databaseName || !username || !password) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  const encryptedPass = await argon2.hash(password);

  const result = await pool.query(
    'INSERT INTO db_connections (tenant_id, name, host, port, database_name, username, encrypted_password) VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id',
    [session.tenantId, name, host, port, databaseName, username, encryptedPass]
  );

  return res.status(201).json({ id: result.rows[0].id });
});

app.listen(3000, () => console.log('Server running on port 3000'));
